/** @deprecated Configure `createChannel({ state })` instead. Action snapshots are stored via `StateStore.kv`. */
export class InMemoryActionStore {
    map = new Map();
    async put(id, snap, ttlMs) {
        this.map.set(id, {
            snap,
            expiresAt: ttlMs ? Date.now() + ttlMs : undefined,
        });
    }
    async get(id) {
        const e = this.map.get(id);
        if (!e)
            return undefined;
        if (e.expiresAt !== undefined && Date.now() > e.expiresAt) {
            this.map.delete(id);
            return undefined;
        }
        return e.snap;
    }
    async delete(id) {
        this.map.delete(id);
    }
    async consume(id) {
        const entry = this.map.get(id);
        if (!entry)
            return undefined;
        if (entry.expiresAt !== undefined && Date.now() > entry.expiresAt) {
            this.map.delete(id);
            return undefined;
        }
        this.map.delete(id);
        return entry.snap;
    }
}
